import{_ as e,o as t,c as o,ag as r}from"./chunks/framework.DGzMGr_a.js";const u=JSON.parse('{"title":"RO3开发团队这回认真了：广告用实机、手动比挂机强、城战大改","description":"RO3 第二期「共创议事录」出炉，开发团队回应了广告不实、手动vs自动、城战改动三个核心问题。我看了之后觉得，这次他们确实在听玩家说话。","frontmatter":{"title":"RO3开发团队这回认真了：广告用实机、手动比挂机强、城战大改","date":"2026-06-10T00:00:00.000Z","description":"RO3 第二期「共创议事录」出炉，开发团队回应了广告不实、手动vs自动、城战改动三个核心问题。我看了之后觉得，这次他们确实在听玩家说话。"},"headers":[],"relativePath":"news/co-creation-report-2.md","filePath":"news/co-creation-report-2.md","lastUpdated":1781699262000}'),p={name:"news/co-creation-report-2.md"};function n(l,a,i,s,c,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="ro3开发团队这回认真了-广告用实机、手动比挂机强、城战大改" tabindex="-1">RO3开发团队这回认真了：广告用实机、手动比挂机强、城战大改 <a class="header-anchor" href="#ro3开发团队这回认真了-广告用实机、手动比挂机强、城战大改" aria-label="Permalink to &quot;RO3开发团队这回认真了：广告用实机、手动比挂机强、城战大改&quot;">​</a></h1><blockquote><p>2026-06-10</p></blockquote><p>前两天巴哈姆特发的共创议事录第二期，我仔细看了一遍。这次讨论的三个问题都是之前玩家吵得最凶的，而且开发团队给的回应比我想的实在。</p><h2 id="广告不实-承诺全用实机画面" tabindex="-1">广告不实？承诺全用实机画面 <a class="header-anchor" href="#广告不实-承诺全用实机画面" aria-label="Permalink to &quot;广告不实？承诺全用实机画面&quot;">​</a></h2><p>第一个话题是广告。这个说实话是现在国产MMO的通病了——宣传片做得跟电影一样，进去一看完全两回事。RO3之前那个首支预告片其实还行，基本都是实机画面剪辑的，但玩家不买账也正常，被坑怕了。</p><p>开发团队这次明确说：以后所有广告内容全部用实际游戏画面，不搞虚假宣传。这个承诺听起来简单，但在国内MMO市场里其实挺难得的。敢这么说的团队，要么是对产品有信心，要么是实在没什么好忽悠的——我觉得RO3可能是前者。</p><h2 id="手动比自动强-不是说说而已" tabindex="-1">手动比自动强，不是说说而已 <a class="header-anchor" href="#手动比自动强-不是说说而已" aria-label="Permalink to &quot;手动比自动强，不是说说而已&quot;">​</a></h2><p>第二个话题是手操和挂机的平衡。RO系列的老玩家都知道，RO1当年外挂横行很大程度上是因为官方放任不管。RO3这次从一开始就说了会有自动战斗，但到底怎么平衡一直没说明白。</p><p>这次他们给了明确方向：<strong>手动操作的效率会显著高于辅助战斗</strong>，而且在核心玩法和竞技模式里会限制自动功能。意思就是平时挂机练级可以，但打副本打GVG想自动？没门。</p><p>我觉得这个思路是对的。现在MMO玩家分两派，一派碎片时间多需要挂机，一派追求操作和挑战。完全取消自动战斗会劝退上班族，但让自动和手动收益一样又没人手动。RO3的方案算是折中——日常能挂，高难必须手操。能不能执行好是另一回事，但方向没问题。</p><h2 id="城战大改-火炮、机甲、华丽金属" tabindex="-1">城战大改：火炮、机甲、华丽金属 <a class="header-anchor" href="#城战大改-火炮、机甲、华丽金属" aria-label="Permalink to &quot;城战大改：火炮、机甲、华丽金属&quot;">​</a></h2><p>第三个话题是GVG城战的调整。之前测试玩家反馈城战里的火炮判定太迷，机甲资源循环也有问题，华丽金属（就是攻城要打的核心）数值不合理。</p><p>开发团队回应说正在改：火炮的判定范围和互动时间在调整，还在考虑加&quot;自动上炮&quot;功能让操作更流畅。华丽金属的防御数值和机甲的资源循环也在重新平衡。</p><p>说实话这些细节调整说明团队确实在按测试反馈做事，不是那种&quot;收到反馈了我们会考虑&quot;的套话。他们是真的去改了具体数值和机制。</p><h2 id="再说说-炖菜理念" tabindex="-1">再说说&quot;炖菜理念&quot; <a class="header-anchor" href="#再说说-炖菜理念" aria-label="Permalink to &quot;再说说&quot;炖菜理念&quot;&quot;">​</a></h2><p>制作人Yu在文章里又提了他们那个&quot;炖菜&quot;开发理念——就是把玩家反馈当食材，慢慢炖出好游戏。听起来有点鸡汤，但从他们实际做的事情来看，至少态度是认真的。</p><p>没有准备好的内容不会推出来——这是Yu的原话。考虑到之前延期了那么多次，他们确实是在这么做。虽然等得确实让人着急，但总比端出个半成品强。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这期共创议事录给我最大的感受是：RO3的开发团队对玩家反馈的处理方式，在现在的MMO市场里算是比较少见的那种。不是做完游戏找玩家测试，而是测试阶段就让玩家参与设计决策。</p><p>当然，说得好听是一回事，做出来是另一回事。马上6月25日启燃测试就开了，到时候游戏到底做成什么样，上手就知道了。</p><p>官网还在预约中：<a href="https://ro3global.com/zh-TW" target="_blank" rel="noreferrer">https://ro3global.com/zh-TW</a></p>',21)])])}const q=e(p,[["render",n]]);export{u as __pageData,q as default};
